@Service
public class OrderProducer {
    @Autowired
    private RabbitTemplate rabbitTemplate;
    public void sendOrderMessage(OrderDTO order) {
        String messageId = UUID.randomUUID().toString();
        rabbitTemplate.convertAndSend(
        "order.exchange",
        "order.routing.key",
        JSON.toJSONString(order),
        message -> {
