### 4.4 消费者
```java
@Component
@Slf4j
public class OrderConsumer {
    @Autowired
    private OrderService orderService;
    @RabbitListener(
    queues = "order.queue",
    concurrency = "1",       // 单线程消费（保证顺序）
    ackMode = "MANUAL"       // 手动确认
    )
    public void handleOrderMessage(Message message, Channel channel) throws IOException {
        long deliveryTag = message.getMessageProperties().getDeliveryTag();
        try {
            String body = new String(message.getBody(), StandardCharsets.UTF_8);
            OrderDTO order = JSON.parseObject(body, OrderDTO.class);
            // 幂等性检查
            if (isProcessed(message.getMessageProperties().getMessageId())) {
                channel.basicAck(deliveryTag, false);
                return;
            }
        // 业务处理
        orderService.processOrder(order);
        // 确认消息
        channel.basicAck(deliveryTag, false);
        log.info("消息处理成功，orderId={}", order.getOrderId());
    } catch (Exception e) {
        log.error("消息处理失败，deliveryTag={}", deliveryTag, e);
        // 拒绝消息，不重新入队（进入死信队列）
        channel.basicNack(deliveryTag, false, false);
    }
}
private boolean isProcessed(String messageId) {
